import{_ as a,c as i,o as t,a5 as s}from"./chunks/framework.FsfTmO4n.js";const m=JSON.parse('{"title":"Viewing Data","description":"","frontmatter":{},"headers":[],"relativePath":"apps/chasm/share/overview.md","filePath":"apps/chasm/share/overview.md"}'),o={name:"apps/chasm/share/overview.md"};function r(l,e,n,d,p,c){return t(),i("div",{"data-pagefind-body":!0},e[0]||(e[0]=[s('<h1 id="viewing-data" tabindex="-1">Viewing Data <a class="header-anchor" href="#viewing-data" aria-label="Permalink to &quot;Viewing Data&quot;">​</a></h1><p>Once a valid device ID and share code are entered, the application displays the shared messages in a user-friendly format, split into various sections.</p><p>Multiple shares can be loaded at once, and remembered, which will display as tabs across the top of the screen.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The first section includes an overview of device and share information, as well as links to download the shared data in a variety of formats.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2026/03/chrome_hqSioXjX9T.png" alt="" tabindex="0"><figcaption></figcaption></figure><p>The download options are:</p><ul><li>All messages <ul><li>JSON: One JSON object per message, with human readable field labels, parsing and formatting of values</li><li>CSV: One column per V3 message field label</li><li>HEX: Raw V3 message data in hexadecimal format</li><li>Base64: Raw V3 message data in Base64 format</li></ul></li><li>Positions: <ul><li>KML (track, points, or both)</li><li>NMEA</li><li>MAP PNG (when locations are included)</li></ul></li></ul><p>Formats may or may not be available depending on the type of shared data.</p>',9)]))}const f=a(o,[["render",r]]);export{m as __pageData,f as default};
